-- =============================================================
-- Fase 3.4: Formulários automáticos (25 tipos) + Páginas dos Equipamentos (CMS por blocos)
-- =============================================================

-- 1. rfq_formulario_tipo: novas colunas slug + codigo_formulario
ALTER TABLE public.rfq_formulario_tipo
  ADD COLUMN IF NOT EXISTS slug text,
  ADD COLUMN IF NOT EXISTS codigo_formulario text;

CREATE UNIQUE INDEX IF NOT EXISTS uq_rfq_formulario_tipo_slug
  ON public.rfq_formulario_tipo (slug) WHERE slug IS NOT NULL;

-- 2. equipamento_pagina (1:1 com o tipo)
CREATE TABLE IF NOT EXISTS public.equipamento_pagina (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tipo_id uuid NOT NULL UNIQUE REFERENCES public.rfq_formulario_tipo(id) ON DELETE CASCADE,
  slug text NOT NULL UNIQUE,
  seo_title_pt text,
  seo_title_es text,
  seo_title_en text,
  seo_description_pt text,
  seo_description_es text,
  seo_description_en text,
  og_image_url text,
  publicado boolean NOT NULL DEFAULT false,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT ON public.equipamento_pagina TO anon;
GRANT SELECT ON public.equipamento_pagina TO authenticated;
GRANT ALL ON public.equipamento_pagina TO service_role;

ALTER TABLE public.equipamento_pagina ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "eqpg_read_public" ON public.equipamento_pagina;
CREATE POLICY "eqpg_read_public" ON public.equipamento_pagina
  FOR SELECT USING (publicado IS TRUE);

DROP POLICY IF EXISTS "eqpg_write_admin" ON public.equipamento_pagina;
CREATE POLICY "eqpg_write_admin" ON public.equipamento_pagina
  FOR ALL TO authenticated
  USING (public.has_role(auth.uid(), 'admin'))
  WITH CHECK (public.has_role(auth.uid(), 'admin'));

DROP POLICY IF EXISTS "eqpg_read_admin" ON public.equipamento_pagina;
CREATE POLICY "eqpg_read_admin" ON public.equipamento_pagina
  FOR SELECT TO authenticated
  USING (public.has_role(auth.uid(), 'admin'));

-- 3. equipamento_pagina_bloco
CREATE TABLE IF NOT EXISTS public.equipamento_pagina_bloco (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  pagina_id uuid NOT NULL REFERENCES public.equipamento_pagina(id) ON DELETE CASCADE,
  tipo_bloco text NOT NULL CHECK (tipo_bloco IN (
    'hero','descricao','especificacoes','beneficios','casos_uso','galeria','faq','video','cta_orcamento'
  )),
  ordem int NOT NULL DEFAULT 0,
  visivel boolean NOT NULL DEFAULT true,
  conteudo_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_eq_bloco_pagina_ordem
  ON public.equipamento_pagina_bloco (pagina_id, ordem);

GRANT SELECT ON public.equipamento_pagina_bloco TO anon;
GRANT SELECT ON public.equipamento_pagina_bloco TO authenticated;
GRANT ALL ON public.equipamento_pagina_bloco TO service_role;

ALTER TABLE public.equipamento_pagina_bloco ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "eqbl_read_public" ON public.equipamento_pagina_bloco;
CREATE POLICY "eqbl_read_public" ON public.equipamento_pagina_bloco
  FOR SELECT USING (
    EXISTS (SELECT 1 FROM public.equipamento_pagina p WHERE p.id = pagina_id AND p.publicado IS TRUE)
  );

DROP POLICY IF EXISTS "eqbl_write_admin" ON public.equipamento_pagina_bloco;
CREATE POLICY "eqbl_write_admin" ON public.equipamento_pagina_bloco
  FOR ALL TO authenticated
  USING (public.has_role(auth.uid(), 'admin'))
  WITH CHECK (public.has_role(auth.uid(), 'admin'));

DROP POLICY IF EXISTS "eqbl_read_admin" ON public.equipamento_pagina_bloco;
CREATE POLICY "eqbl_read_admin" ON public.equipamento_pagina_bloco
  FOR SELECT TO authenticated
  USING (public.has_role(auth.uid(), 'admin'));

-- 4. Função utilitária: criar página + blocos default para um tipo
CREATE OR REPLACE FUNCTION public.provisionar_pagina_equipamento(_tipo_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_slug text;
  v_nome text;
  v_pagina_id uuid;
BEGIN
  SELECT COALESCE(slug, regexp_replace(lower(codigo), '_', '-', 'g')), nome_pt
    INTO v_slug, v_nome
  FROM public.rfq_formulario_tipo WHERE id = _tipo_id;

  IF v_slug IS NULL THEN RETURN NULL; END IF;

  INSERT INTO public.equipamento_pagina (tipo_id, slug, seo_title_pt, seo_description_pt, publicado)
  VALUES (_tipo_id, v_slug, v_nome || ' — Solutek',
    'Solução Solutek para ' || v_nome || '. Solicite orçamento personalizado com engenharia dedicada.',
    false)
  ON CONFLICT (tipo_id) DO UPDATE SET slug = EXCLUDED.slug
  RETURNING id INTO v_pagina_id;

  -- Blocos default (só se ainda não houver nenhum)
  IF NOT EXISTS (SELECT 1 FROM public.equipamento_pagina_bloco WHERE pagina_id = v_pagina_id) THEN
    INSERT INTO public.equipamento_pagina_bloco (pagina_id, tipo_bloco, ordem, conteudo_json) VALUES
    (v_pagina_id, 'hero', 10, jsonb_build_object(
      'eyebrow_pt', 'EQUIPAMENTO INDUSTRIAL',
      'titulo_pt', v_nome,
      'subtitulo_pt', 'Engenharia dedicada para a sua linha. Projeto, fabricação e comissionamento sob medida.',
      'cta_label_pt', 'Solicitar orçamento',
      'imagem_url', ''
    )),
    (v_pagina_id, 'descricao', 20, jsonb_build_object(
      'eyebrow_pt', 'APRESENTAÇÃO',
      'titulo_pt', 'Uma máquina, resultados que ficam.',
      'texto_pt', 'A ' || v_nome || ' da Solutek é projetada para atender indústrias exigentes com foco em confiabilidade, cadência estável e integração com sua linha existente.',
      'bullets_pt', jsonb_build_array(
        'Projeto de engenharia dedicado ao seu produto',
        'Construção sanitária em aço inox AISI 304 / 316L',
        'CLP padrão de mercado, com IHM e Indústria 4.0 ready',
        'Testes com sua amostra antes do FAT'
      ),
      'imagem_url', ''
    )),
    (v_pagina_id, 'especificacoes', 30, jsonb_build_object(
      'eyebrow_pt', 'ESPECIFICAÇÕES TÉCNICAS',
      'titulo_pt', 'Configuração técnica padrão.',
      'descricao_pt', 'Personalizamos cada projeto de acordo com o seu produto, formato e cadência.',
      'itens', jsonb_build_array(
        jsonb_build_object('label_pt','Cadência','valor_pt','sob consulta'),
        jsonb_build_object('label_pt','Formato','valor_pt','sob medida'),
        jsonb_build_object('label_pt','Tensão','valor_pt','220 / 380 / 440 V'),
        jsonb_build_object('label_pt','Construção','valor_pt','AISI 304 / 316L'),
        jsonb_build_object('label_pt','Controle','valor_pt','CLP + IHM 7"'),
        jsonb_build_object('label_pt','Certificação','valor_pt','conforme demanda')
      )
    )),
    (v_pagina_id, 'beneficios', 40, jsonb_build_object(
      'eyebrow_pt', 'DESTAQUES',
      'titulo_pt', 'Engenharia que reduz o custo por unidade.',
      'descricao_pt', 'Cada componente é escolhido para maximizar OEE — sem dependência de fornecedor exclusivo.',
      'itens', jsonb_build_array(
        jsonb_build_object('icone','Gauge','titulo_pt','Alta performance','texto_pt','Cadência estável mesmo em produtos com variabilidade.'),
        jsonb_build_object('icone','Settings2','titulo_pt','Setup rápido','texto_pt','Troca de formato em minutos, reduzindo downtime.'),
        jsonb_build_object('icone','ShieldCheck','titulo_pt','Padrão sanitário','texto_pt','Design CIP-friendly conforme GMP.'),
        jsonb_build_object('icone','Zap','titulo_pt','Pronta para integração','texto_pt','CLP aberto, OPC-UA e dashboards em tempo real.')
      )
    )),
    (v_pagina_id, 'cta_orcamento', 90, jsonb_build_object(
      'titulo_pt', 'Pronto para automatizar a sua linha?',
      'subtitulo_pt', 'Fale com nosso time e receba um projeto sob medida — do dimensionamento ao FAT.',
      'cta_label_pt', 'Solicitar orçamento'
    ));
  END IF;

  RETURN v_pagina_id;
END;
$fn$;

-- 5. Trigger: ao criar novo tipo RFQ, auto-provisiona página
CREATE OR REPLACE FUNCTION public.trg_auto_pagina_equipamento()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $t$
BEGIN
  IF NEW.slug IS NULL THEN
    NEW.slug := regexp_replace(lower(NEW.codigo), '_', '-', 'g');
  END IF;
  RETURN NEW;
END;
$t$;

DROP TRIGGER IF EXISTS trg_rfq_tipo_slug ON public.rfq_formulario_tipo;
CREATE TRIGGER trg_rfq_tipo_slug BEFORE INSERT OR UPDATE ON public.rfq_formulario_tipo
FOR EACH ROW EXECUTE FUNCTION public.trg_auto_pagina_equipamento();

CREATE OR REPLACE FUNCTION public.trg_provisionar_pagina_after()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $t$
BEGIN
  PERFORM public.provisionar_pagina_equipamento(NEW.id);
  RETURN NEW;
END;
$t$;

DROP TRIGGER IF EXISTS trg_rfq_tipo_provisionar ON public.rfq_formulario_tipo;
CREATE TRIGGER trg_rfq_tipo_provisionar AFTER INSERT ON public.rfq_formulario_tipo
FOR EACH ROW EXECUTE FUNCTION public.trg_provisionar_pagina_after();


